import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';

import { Card, Grid, Button, Typography } from '@mui/material';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { DemoContainer } from '@mui/x-date-pickers/internals/demo';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import 'dayjs/locale/en-gb';
import TextField from '@mui/material/TextField';
import InputLabel from '@mui/material/InputLabel';
import { axios } from '../../utils/axios';
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import GoBackButton from '../../components/goBackButton/GoBackButton';
import InputField from '../../components/input/inputField';

export default function AddaminPage() {
  const navigate = useNavigate();
  const [ddesc, setDdesc] = useState('');
  const [dpercent, setDpercent] = useState('');
  const [dtitle, setDtitle] = useState('');
  const [dcode, setDcode] = useState('');
  const [dstart, setDstart] = useState('');
  const [dend, setDend] = useState('');
  const [profilePic, setProfilePic] = useState(false);
  const [imagepreview, setImagepreview] = useState(null);
  const [error, setError] = useState('');
  const { i18 } = useMyContext();

  const isAddButtonDisabled = !ddesc || !dpercent || !dtitle || !dcode || !dstart || !dend;

  const backtouser = () => {
    navigate('/dashboard/offers');
  };

  const addOffer = async () => {
    try {
      const updatedValues = new FormData();
      updatedValues.append('offer', profilePic);
      updatedValues.append('percentage', dpercent);
      updatedValues.append('desc', ddesc);
      updatedValues.append('title', dtitle);
      updatedValues.append('code', dcode);
      updatedValues.append('startDate', dstart?.format(''));
      updatedValues.append('endDate', dend?.format(''));

      const res = await axios.post('module/listing/discountCode', updatedValues);
      if (res.status === 200) {
        GenerateToastConfig(res.data.message, 'success');
        navigate('/dashboard/offers');
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };
  const handleChange = (e) => {
    const numericInput = e.target.value;
    setDpercent(numericInput);

    if (/^\d{1}?$/.test(numericInput)) {
      setError('Invalid offer percentage');
    } else {
      setError('');
    }
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    const reader = new FileReader();

    reader.onloadend = () => {
      setImagepreview(reader.result);
      setProfilePic(file);
    };

    if (file) {
      reader.readAsDataURL(file);
    }
  };

  return (
    <>
      <Helmet>
        <title> Add Offer </title>
      </Helmet>
      <Card sx={{ padding: '20px 10px', margin: '30px 0px' }}>
        <Grid container sx={{ borderBottom: '1px solid #dbe0e4', padding: '10px 0px' }}>
          <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
            <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
              {i18?.SETTINGSLIST?.ADD_OFFERS || "Add Offers"}
            </Typography>
            {/* <Button variant="contained" onClick={backtouser} startIcon={<Iconify icon="icon-park-twotone:back" />}>
              {i18?.SETTINGSLIST?.GO_BACK || "Go Back"}
            </Button> */}
            <GoBackButton
              label={i18?.SETTINGSLIST?.GO_BACK || "Go Back"}
              onClick={backtouser}
              icon="icon-park-twotone:back"
            />
          </Grid>
        </Grid>
        <Grid container sx={{ marginTop: '10px' }}>
          <Grid item xs={6} sx={{ padding: '0px 5px' }}>
            <InputField
              value={dtitle}
              name="FirstName"
              label={i18?.SETTINGSLIST?.DISCOUNT_TITLE || "Discount Title"}
              sx={{ margin: '10px 0px', width: '100%' }}
              onChange={(e) => setDtitle(e.target.value)}
            />
          </Grid>
          <Grid item xs={6} sx={{ padding: '0px 5px' }}>
            <InputField
              value={dcode}
              name="LastName"
              label={i18?.SETTINGSLIST?.DISCOUNT_CODE || "Discount Code"}
              sx={{ margin: '10px 0px', width: '100%' }}
              onChange={(e) => setDcode(e.target.value)}
            />
          </Grid>
          <Grid item xs={6} sx={{ padding: '0px 5px' }}>
            <InputField
              type="number"
              value={dpercent}
              name="discountpercentage"
              label={i18?.SETTINGSLIST?.DISCOUNT_PERCENTAGE || "Discount Percentage"}
              sx={{ margin: '10px 0px', width: '100%' }}
              onChange={handleChange}
              inputProps={{ inputMode: 'numeric', pattern: '[0-9]*' }}
              error={!!error}
              helperText={error}
            />
          </Grid>
          <Grid item xs={6} sx={{ padding: '0px 5px' }}>
            <InputField
              value={ddesc}
              name="EmailAddress"
              label={i18?.SETTINGSLIST?.DISCOUNT_DESCRIPTION || "Discount Description"}
              sx={{ margin: '10px 0px', width: '100%' }}
              onChange={(e) => setDdesc(e.target.value)}
            />
          </Grid>
          <Grid item xs={6} sx={{ padding: '0px 5px' }}>
            <InputLabel id="demo-simple-select-label">{i18?.SETTINGSLIST?.DISCOUNT_START || "Discount Start"}</InputLabel>
            <LocalizationProvider dateAdapter={AdapterDayjs} adapterLocale="en-gb">
              <DemoContainer components={['DatePicker']}>
                <DatePicker
                  sx={{ width: 1 }}
                  defaultValue={null}
                  disablePast
                  views={['year', 'month', 'day']}
                  onChange={(newValue) => setDstart(newValue)}
                />
              </DemoContainer>
            </LocalizationProvider>
          </Grid>
          <Grid item xs={6} sx={{ padding: '0px 5px' }}>
            <InputLabel id="demo-simple-select-label">{i18?.SETTINGSLIST?.DISCOUNT_END || "Discount End"}</InputLabel>
            <LocalizationProvider dateAdapter={AdapterDayjs} adapterLocale="en-gb">
              <DemoContainer components={['DatePicker']}>
                <DatePicker
                  sx={{ width: 1 }}
                  defaultValue={null}
                  disablePast
                  minDate={dstart} // Set the minimum date to be the selected start date
                  views={['year', 'month', 'day']}
                  onChange={(newValue) => setDend(newValue)}
                />
              </DemoContainer>
            </LocalizationProvider>
          </Grid>
          <Grid item xs={6} sx={{ padding: '10px 5px' }}>
            <InputLabel id="demo-simple-select-label">{i18?.SETTINGSLIST?.DISCOUNT_PIC || "Discount Picture"}</InputLabel>
            <TextField
              type="file"
              sx={{ margin: '10px 0px', width: '100%' }}
              name="profilepic"
              onChange={(e) => handleImageChange(e)}
            />
            {imagepreview && (
              <div
                style={{
                  marginTop: '10px',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '10px',
                }}
              >
                <img
                  src={imagepreview}
                  alt="Preview"
                  style={{
                    width: '80px',
                    height: '80px',
                    borderRadius: '8px',
                    objectFit: 'cover',
                    border: '1px solid #ccc',
                    boxShadow: '0 2px 6px rgba(0, 0, 0, 0.1)',
                  }}
                />
                {/* <Button
                  variant="outlined"
                  color="error"
                  onClick={() => {
                    setImagepreview(null);
                    setProfilePic(false);
                  }}
                >
                  Remove
                </Button> */}
              </div>
            )}
          </Grid>
        </Grid>
        <Grid container justifyContent="flex-end" sx={{ paddingRight: '20px' }}>
          <Button variant="contained" disabled={isAddButtonDisabled} onClick={() => addOffer()}>
            {i18?.SETTINGSLIST?.ADD || "Add"}
          </Button>
        </Grid>
      </Card>
    </>
  );
}
